// Package backup packs and restores the irreplaceable state of a co-located
// controller+master node: the controller's store db, CA, manifest, and sops
// secrets file, plus the master's wg-easy client db, admin password, and node
// identity. Everything else (nft, mihomo/xray/blocky configs, compose files) is
// regenerated by the agent's reconcile loop and is deliberately not captured.
package backup

import (
	"archive/tar"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
)

// Layer marks which half of a co-located node an item belongs to.
type Layer string

const (
	LayerController Layer = "controller"
	LayerMaster     Layer = "master"
)

// ArchiveSchema is the on-disk archive format version. Bump only on a
// backward-incompatible change to the tar layout or manifest shape.
const ArchiveSchema = 1

const manifestName = "manifest.json"

// Item is one file captured in a backup. Archives are small, so contents are
// held in memory.
type Item struct {
	Name  string      // path inside the tar, e.g. "controller/state.db"
	Dest  string      // absolute restore destination
	Mode  os.FileMode // original file mode
	Layer Layer
	Data  []byte
}

// Entry is an Item's manifest record (no file contents).
type Entry struct {
	Name  string `json:"name"`
	Dest  string `json:"dest"`
	Mode  uint32 `json:"mode"`
	Layer Layer  `json:"layer"`
}

// Manifest is the archive's self-description, stored as the tar member
// "manifest.json" and read first on restore to validate compatibility.
type Manifest struct {
	Schema      int     `json:"schema"`
	WireVersion int     `json:"wire_version"`
	Layers      []Layer `json:"layers"`
	Entries     []Entry `json:"entries"`
	CreatedAt   string  `json:"created_at"`
}

// BuildTar writes the manifest followed by every item into a tar archive.
func BuildTar(m Manifest, items []Item) ([]byte, error) {
	var buf bytes.Buffer
	tw := tar.NewWriter(&buf)

	mj, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("marshal manifest: %w", err)
	}
	if err := writeTar(tw, manifestName, 0o600, mj); err != nil {
		return nil, err
	}
	for _, it := range items {
		if err := writeTar(tw, it.Name, it.Mode, it.Data); err != nil {
			return nil, err
		}
	}
	if err := tw.Close(); err != nil {
		return nil, fmt.Errorf("close tar: %w", err)
	}
	return buf.Bytes(), nil
}

func writeTar(tw *tar.Writer, name string, mode os.FileMode, data []byte) error {
	hdr := &tar.Header{Name: name, Mode: int64(mode.Perm()), Size: int64(len(data)), Typeflag: tar.TypeReg}
	if err := tw.WriteHeader(hdr); err != nil {
		return fmt.Errorf("tar header %q: %w", name, err)
	}
	if _, err := tw.Write(data); err != nil {
		return fmt.Errorf("tar write %q: %w", name, err)
	}
	return nil
}

// ParseTar reads the manifest and items back out of a tar archive.
func ParseTar(data []byte) (Manifest, []Item, error) {
	tr := tar.NewReader(bytes.NewReader(data))
	var (
		m      Manifest
		gotM   bool
		items  []Item
		byName = map[string]Entry{}
	)
	for {
		hdr, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return Manifest{}, nil, fmt.Errorf("read tar: %w", err)
		}
		payload, err := io.ReadAll(tr)
		if err != nil {
			return Manifest{}, nil, fmt.Errorf("read %q: %w", hdr.Name, err)
		}
		if hdr.Name == manifestName {
			if err := json.Unmarshal(payload, &m); err != nil {
				return Manifest{}, nil, fmt.Errorf("unmarshal manifest: %w", err)
			}
			if m.Schema != ArchiveSchema {
				return Manifest{}, nil, fmt.Errorf("unsupported archive schema %d (want %d)", m.Schema, ArchiveSchema)
			}
			for _, e := range m.Entries {
				byName[e.Name] = e
			}
			gotM = true
			continue
		}
		items = append(items, Item{Name: hdr.Name, Mode: os.FileMode(hdr.Mode), Data: payload})
	}
	if !gotM {
		return Manifest{}, nil, fmt.Errorf("archive has no %s", manifestName)
	}
	// Backfill Dest/Layer/Mode from the manifest entries (authoritative).
	for i := range items {
		if e, ok := byName[items[i].Name]; ok {
			items[i].Dest = e.Dest
			items[i].Layer = e.Layer
			items[i].Mode = os.FileMode(e.Mode)
		}
	}
	return m, items, nil
}
